const items = $input.all()[0].json.vulnerabilities || [];

const extracted = items.map(item => {
  const cve = item.cve.id;

  const cvssMetric =
    item.cve.metrics?.cvssMetricV31?.[0] ||
    item.cve.metrics?.cvssMetricV30?.[0] ||
    item.cve.metrics?.cvssMetricV2?.[0];

  const cvss = cvssMetric?.cvssData?.baseScore ?? null;
  const cvss_vector = cvssMetric?.cvssData?.vectorString ?? null;

  const description = (
    item.cve.descriptions?.[0]?.value || 'No description available'
  ).substring(0, 500);

  const publishedDate = item.cve.published || null;

  return {
    cve,
    cvss,
    cvss_vector,
    description,
    publishedDate,
    timestamp: new Date().toISOString()
  };
});

return extracted.map(item => ({ json: { item } }));

const items = $input.all()
  .map(entry => entry.json.item)
  .filter(item => item && item.cve);

if (items.length === 0) return [];

const EPSS_BASE_URL = 'https://api.first.org/data/v1/epss';
const EPSS_BATCH_SIZE = 100;

async function fetchEpss(cveList) {
  const url = EPSS_BASE_URL + '?cve=' + encodeURIComponent(cveList.join(','));
  const response = await $http.get(url, {
    timeout: 30000,
    headers: { 'User-Agent': 'grupo-x-thesis/2.0' }
  });
  const records = (response && response.data) || [];
  const map = {};
  for (const record of records) {
    if (record && record.cve) {
      map[record.cve] = {
        epss: parseFloat(record.epss),
        percentile: parseFloat(record.percentile),
        date: record.date
      };
    }
  }
  return map;
}

async function main() {
  let epssMap = {};
  let batchError = null;

  try {
    for (let i = 0; i < items.length; i += EPSS_BATCH_SIZE) {
      const chunk = items.slice(i, i + EPSS_BATCH_SIZE).map(item => item.cve);
      const partial = await fetchEpss(chunk);
      Object.assign(epssMap, partial);
    }
  } catch (error) {
    batchError = error;
  }

  return items.map(item => {
    const entry = {
      cve: item.cve,
      cvss: item.cvss != null ? Math.min(Math.max(parseFloat(item.cvss) || 0, 0), 10) : null,
      cvss_vector: item.cvss_vector || null,
      description: (item.description || '').trim(),
      publishedDate: item.publishedDate || null,
      normalized_timestamp: new Date().toISOString(),
      epss: null,
      epss_percentile: null,
      epss_date: null,
      epss_source: null,
      processing_status: null,
      error_reason: null
    };

    if (batchError) {
      entry.processing_status = 'error';
      entry.error_reason = 'Error de red en API EPSS: ' + (batchError.message || 'desconocido');
    } else if (entry.cvss == null) {
      entry.processing_status = 'error';
      entry.error_reason = 'CVSS no disponible en NVD';
    } else if (epssMap[item.cve]) {
      entry.epss = epssMap[item.cve].epss;
      entry.epss_percentile = epssMap[item.cve].percentile;
      entry.epss_date = epssMap[item.cve].date;
      entry.epss_source = 'first.org';
      entry.processing_status = 'success';
    } else {
      entry.epss_source = 'unavailable';
      entry.processing_status = 'no_epss';
      entry.error_reason = 'CVE no encontrado en FIRST EPSS';
    }

    return { json: { item: entry } };
  });
}

return await main();

const item = $json.item;
const searchText = (item.description || '').toLowerCase();

let asset = 'Sistema General';
let criticality = 5;

if (searchText.includes('nginx')) {
  asset = 'Servidor Nginx';
  criticality = 10;
} else if (searchText.includes('apache')) {
  asset = 'Servidor Apache';
  criticality = 8;
} else if (searchText.includes('wordpress')) {
  asset = 'Aplicación WordPress';
  criticality = 6;
} else if (searchText.includes('tomcat')) {
  asset = 'Servidor Tomcat';
  criticality = 8;
} else if (searchText.includes('kubernetes') || searchText.includes('k8s')) {
  asset = 'Orquestador Kubernetes';
  criticality = 9;
} else if (searchText.includes('docker') || searchText.includes('container')) {
  asset = 'Plataforma Docker';
  criticality = 7;
} else if (searchText.includes('linux')) {
  asset = 'Servidor Linux';
  criticality = 6;
} else if (searchText.includes('windows')) {
  asset = 'Servidor Windows';
  criticality = 6;
} else if (searchText.includes('.net') || searchText.includes('asp.net')) {
  asset = 'Plataforma .NET';
  criticality = 7;
} else if (searchText.includes('mysql') || searchText.includes('postgresql') || searchText.includes('sql server')) {
  asset = 'Base de Datos';
  criticality = 9;
} else if (searchText.includes('redis')) {
  asset = 'Cache Redis';
  criticality = 5;
}

return [{
  json: {
    item: {
      ...item,
      correlated_asset: asset,
      asset_criticality: criticality
    }
  }
}];

const item = $json.item;

let irc = null;

if (item.cvss != null && item.epss != null && item.asset_criticality != null) {
  // IRC = CVSS (40%) + EPSS (40%) + Asset Criticality (20%)
  irc =
    (item.cvss * 0.4) +
    (item.epss * 10 * 0.4) +
    (item.asset_criticality * 0.2);
  irc = parseFloat(Math.min(irc, 10).toFixed(2));
}

return [{ json: { item: { ...item, irc } } }];

if (!$json || !$json.item) return [];

const item = $json.item;

return [{
  json: {
    item: {
      ...item,
      is_critical: true,
      severity_override: 'Crítica',
      alert_event: 'CRITICAL_ALERT_GENERATED'
    }
  }
}];

if (!$json || !$json.item) return [];

const item = $json.item;

let severity = null;

if (item.irc != null) {
  if (item.irc >= 7.5) {
    severity = 'Crítica';
  } else if (item.irc >= 5.0) {
    severity = 'Alta';
  } else if (item.irc >= 2.5) {
    severity = 'Media';
  } else {
    severity = 'Baja';
  }
}

return [{
  json: {
    item: {
      ...item,
      is_critical: false,
      severity_override: severity,
      alert_event: null
    }
  }
}];

const item = $json.item;
if (!item) return [];

const description = (item.description || '').toLowerCase();
const asset = (item.correlated_asset || '').toLowerCase();

async function matchCompanies() {
  try {
    const response = await $http.get('http://host.docker.internal:8000/webhook/n8n/empresas', {
      headers: { 'x-api-key': 'grp-x-n8n-secret-2025' }
    });
    const companies = Array.isArray(response) ? response : (response.data || []);

    const scored = companies.map((company) => {
      const techs = company.technologies || [];
      let score = 0;
      let matchedTechnology = null;

      for (const technology of techs) {
        const technologyLower = technology.toLowerCase();
        const matchesDescription = description.includes(technologyLower);
        const matchesAsset = asset.includes(technologyLower);

        if (matchesDescription) {
          score += 2;
          if (!matchedTechnology) matchedTechnology = technology;
        }

        if (matchesAsset) {
          score += 1;
          if (!matchedTechnology) matchedTechnology = technology;
        }
      }

      return { company, score, matchedTechnology };
    });

    let matchedCompanies = scored.filter((entry) => entry.score > 0).sort((left, right) => right.score - left.score);

    if (matchedCompanies.length === 0 && scored.length > 0) {
      matchedCompanies = [scored[0]];
    }

    const severity = item.severity_override;
    const analyst_id = severity === 'Crítica' || severity === 'Alta' ? 2 : 3;

    return matchedCompanies.map((entry) => ({
      json: {
        payload: {
          cve: item.cve,
          description: item.description,
          affected_technology: entry.matchedTechnology,
          irc: item.irc,
          severity,
          status: 'Pendiente',
          company_id: entry.company.id,
          assigned_analyst_id: analyst_id,
          cvss: item.cvss,
          cvss_vector: item.cvss_vector,
          epss: item.epss,
          epss_date: item.epss_date,
          epss_percentile: item.epss_percentile,
          asset_criticality: item.asset_criticality,
          epss_source: item.epss_source,
          published_date: item.publishedDate,
          processing_status: item.processing_status,
          error_reason: item.error_reason
        }
      }
    }));
  } catch (error) {
    console.error('Error matching companies:', error.message);

    const severity = item.severity_override;
    const analyst_id = severity === 'Crítica' || severity === 'Alta' ? 2 : 3;

    return [{
      json: {
        payload: {
          cve: item.cve,
          description: item.description,
          affected_technology: null,
          irc: item.irc,
          severity,
          status: 'Pendiente',
          company_id: 1,
          assigned_analyst_id: analyst_id,
          cvss: item.cvss,
          cvss_vector: item.cvss_vector,
          epss: item.epss,
          epss_date: item.epss_date,
          epss_percentile: item.epss_percentile,
          asset_criticality: item.asset_criticality,
          epss_source: item.epss_source,
          published_date: item.publishedDate,
          processing_status: item.processing_status,
          error_reason: item.error_reason
        }
      }
    }];
  }
}

return await matchCompanies();

const allResults = $input.all();

let successCount = 0;
let skippedCount = 0;
let errorCount = 0;

allResults.forEach(result => {
  if (result.json && result.json.payload) {
    successCount++;
  } else if (result.json && result.json.exists === true) {
    skippedCount++;
  } else {
    errorCount++;
  }
});

return [{
  json: {
    execution_summary: {
      timestamp: new Date().toISOString(),
      total_processed: successCount + skippedCount + errorCount,
      created: successCount,
      skipped_duplicates: skippedCount,
      errors: errorCount,
      status: errorCount === 0 ? 'SUCCESS' : 'PARTIAL_SUCCESS'
    }
  }
}];
